//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:			HE_AnalogControl_OmronNX
//	CREATOR:		Helgevold - William Veim
// 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	VERSION			DATE					SIGN							DESCRIPTION
//	1.0.0					2026-04-27			William Veim				Initial release
//
//================================================================================================================================
//
//		FUNCTIONALITY:
//
//===============================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)
 
Ext_AnalogControl.EXT_Engineering.Auto_Visible:= Cfg_Auto_InUse;
Ext_AnalogControl.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
FB_AnalogControl_Logic.Cfg_FeedbackValue_Type:=	FALSE;
FB_AnalogControl_Logic.Cfg_OutputValue_Type:=		FALSE;

IF  NOT Ext_AnalogControl.INT_Data.Initialise THEN
	
	//Common parameters are initialised in logic block
	
	//State config
	Ext_AnalogControl.EXT_Engineering.StateCfg_3.Cfg_Quality:=1; //Output module fault = Equipment failiure
	Ext_AnalogControl.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //Output module fault = Alarm
	Ext_AnalogControl.EXT_Engineering.StateCfg_4.Cfg_Quality:=1; //Feedback module fault = Equipment failiure
	Ext_AnalogControl.EXT_Engineering.StateCfg_4.Cfg_Alarm:=TRUE; //Feedback module fault = Alarm
	Ext_AnalogControl.EXT_Engineering.StateCfg_5.Cfg_Quality:=1; //Feedback value fault = Equipment failiure
	Ext_AnalogControl.EXT_Engineering.StateCfg_5.Cfg_Alarm:=TRUE; //Feedback value fault = Alarm
	
	//Initialise set true in logic block
	
END_IF;
	
(*************************************************************************
 *	SCALING FEEDBACK VALUE (from raw value, to signal value)
 *************************************************************************)
 
Wrk_InpSignalValue_Y0 := 				Cfg_FeedbackSignalValue_Y0;
Wrk_InpSignalValue_Y1 :=				Cfg_FeedbackSignalValue_Y1;
Wrk_InpSignalValue_Min := 			Cfg_FeedbackSignalValue_Min;
Wrk_InpSignalValue_Max := 			Cfg_FeedbackSignalValue_Max;
Wrk_InpSignalValue_Unit := 			Cfg_FeedbackSignalValue_Unit;
Wrk_InpRawValue_LoopBreak := 	Cfg_FeedbackRawValue_LoopBreak;
Wrk_InpRawValue_X0 := 					Cfg_FeedbackRawValue_X0;
Wrk_InpRawValue_X1 := 					Cfg_FeedbackRawValue_X1;
Wrk_InpRawValue_Min := 				Cfg_FeedbackRawValue_Min;
Wrk_InpRawValue_Max := 				Cfg_FeedbackRawValue_Max;

//Scaling raw value to signal value (ex 0-8000 -> 4-20mA)
IF Inp_FeedbackRawValue <> Wrk_InpRawValue_LoopBreak THEN
	
	FB_AnalogControl_Logic.Inp_FeedbackValue:=ScaleTrans(SclIn:=INT_TO_REAL(Inp_FeedbackRawValue), 
																									X0:=Wrk_InpRawValue_X0 , 
																									Y0:=Wrk_InpSignalValue_Y0, 
																									X1:=Wrk_InpRawValue_X1, 
																									Y1:=Wrk_InpSignalValue_Y1);
ELSE
	FB_AnalogControl_Logic.Inp_FeedbackValue:=0;
END_IF;

(*************************************************************************
 *	SCALING OUTPUT VALUE (from signal value, to raw value)
 *************************************************************************)

Wrk_OutSignalValue_X0 := Cfg_OutputSignalValue_X0;
Wrk_OutSignalValue_X1 := Cfg_OutputSignalValue_X1;
Wrk_OutSignalValue_Min := Cfg_OutputSignalValue_Min;
Wrk_OutSignalValue_Max := Cfg_OutputSignalValue_Max;
Wrk_OutSignalValue_Unit := Cfg_OutputSignalValue_Unit;
Wrk_OutRawValue_Y0 := Cfg_OutputRawValue_Y0;
Wrk_OutRawValue_Y1 := Cfg_OutputRawValue_Y1;
Wrk_OutRawValue_Min := Cfg_OutputRawValue_Min;
Wrk_OutRawValue_Max  := Cfg_OutputRawValue_Max;

//Scaling signal value to raw value (ex 4-20mA -> 0-8000)
Out_Output:=REAL_TO_INT(ScaleTrans(SclIn:=FB_AnalogControl_Logic.Out_Output, 
																X0:=Wrk_OutSignalValue_X0, 
																Y0:=Wrk_OutRawValue_Y0, 
																X1:=Wrk_OutSignalValue_X1, 
																Y1:=Wrk_OutRawValue_Y1));

(*************************************************************************
 *	FAULT CONTROL
 *************************************************************************)

Wrk_FeedbackModuleFault:=	Inp_ModuleFault_Feedback;
Wrk_OutputModuleFault:=		Inp_ModuleFault_Output;
TON_FeedbackValueFault(In:=(FB_AnalogControl_Logic.Inp_FeedbackValue < (Wrk_InpSignalValue_Y0 * 0.95) OR FB_AnalogControl_Logic.Inp_FeedbackValue > (Wrk_InpSignalValue_Y1 * 1.05)),
										PT:=TIME#10s);

Wrk_FeedbackValue_Fault := 	TON_FeedbackValueFault.Q OR
												Inp_FeedbackRawValue=Wrk_InpRawValue_LoopBreak;

(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)
 //STATE 1 - Locked to "Interlock"
 //STATE 1 - Locked to "Deviation fault"

//STATE 3 - Output module fault
FB_AnalogControl_Logic.Cfg_State3_InUse:=TRUE;
FB_AnalogControl_Logic.Inp_State3_State:=Wrk_OutputModuleFault;
FB_AnalogControl_Logic.Inp_State3_Desc:= 'Output module fault';

//STATE 4 - Feedback module fault
FB_AnalogControl_Logic.Cfg_State4_InUse:=TRUE;
FB_AnalogControl_Logic.Inp_State4_State:=Wrk_FeedbackModuleFault;
FB_AnalogControl_Logic.Inp_State4_Desc:= 'Feedback module fault';

//STATE 5 - Feedback value fault
FB_AnalogControl_Logic.Cfg_State5_InUse:=TRUE;
FB_AnalogControl_Logic.Inp_State5_State:=Wrk_FeedbackValue_Fault;
FB_AnalogControl_Logic.Inp_State5_Desc:= 'Feedback value fault';

(*************************************************************************
 *	IO UPDATE AND EXECUTE LOGIC BLOCK
 *************************************************************************)
 
 //Block spesific parameteres
FB_AnalogControl_Logic.Cfg_FeedbackValue_Max:=	Wrk_InpSignalValue_Max;
FB_AnalogControl_Logic.Cfg_FeedbackValue_Min:=	Wrk_InpSignalValue_Min;
FB_AnalogControl_Logic.Cfg_FeedbackValue_Type:=	FALSE;
FB_AnalogControl_Logic.Cfg_OutputValue_Max:=		Wrk_OutSignalValue_Max;
FB_AnalogControl_Logic.Cfg_OutputValue_Min:=		Wrk_OutSignalValue_Min;
FB_AnalogControl_Logic.Cfg_OutputValue_Type:=		FALSE;

//Updating strucutre
Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_Unit:=	Wrk_InpSignalValue_Unit;
Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Unit:=		Wrk_OutSignalValue_Unit;

//General parameters
FB_AnalogControl_Logic.Cfg_FeedbackValue_X0:=			Wrk_InpSignalValue_Y0;
FB_AnalogControl_Logic.Cfg_FeedbackValue_X1:=			Wrk_InpSignalValue_Y1;
FB_AnalogControl_Logic.Cfg_OutputValue_Y0:=				Wrk_OutSignalValue_X0;
FB_AnalogControl_Logic.Cfg_OutputValue_Y1:=				Wrk_OutSignalValue_X1;
FB_AnalogControl_Logic.Cfg_ControlCabinet:=				Cfg_ConnCabinet;
FB_AnalogControl_Logic.Cfg_ControllerTAG:=				Cfg_ControllerName;
FB_AnalogControl_Logic.Cfg_Interlock_InUse:=				Cfg_Interlock_InUse;
FB_AnalogControl_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
FB_AnalogControl_Logic.Inp_FeedbackValue_Fault:=		Wrk_FeedbackValue_Fault;
FB_AnalogControl_Logic.Inp_AlmSuppressDesc:=			Inp_AlmSuppressDesc;
FB_AnalogControl_Logic.Inp_AlmSuppress:=					Inp_AlmSuppress;
FB_AnalogControl_Logic.Inp_Auto_Engage:=					Inp_AutoStartRef;
FB_AnalogControl_Logic.Inp_Auto_Gain:=						Inp_AutoOutputRef;
FB_AnalogControl_Logic.Inp_Interlock:=							Inp_Interlock;
FB_AnalogControl_Logic.Inp_LocalMode:=						Inp_LocalMode;

FB_AnalogControl_Logic(ENS:=TRUE, 
											Ext_AnalogControl:=Ext_AnalogControl, 
											Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	UPDATING BLOCK IO
 *************************************************************************)

Sts_AvailableAuto:=FB_AnalogControl_Logic.Sts_AutoAvailable;
Sts_Alarm:=				FB_AnalogControl_Logic.Sts_AlarmTriggered;
